// @vitest-environment jsdom

import { act, createElement } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import type { OpenCompanyClient } from "@/api/client";
import type { SetupStatus } from "@/api/setup";
import { SetupWizard } from "@/views/setup/SetupWizard";

/**
 * A host that already reaches a model must not ask its operator for one.
 *
 * `GET /api/v1/setup` answers `inference.ready` whenever a platform credential
 * resolves from the environment — a hosted tenant's projected token, or a
 * static key on the process. That operator has no key of their own and no way
 * to obtain one, so the model step is a question with a single possible answer
 * and a key field nobody can fill.
 *
 * Three things are pinned here, and the third is the one that matters most:
 * the step is gone and the progress bar is a step shorter; the apply stores no
 * inference provider, because the host resolves the managed endpoint from its
 * own environment and writing one would record a decision the operator never
 * made; and a host that is *not* ready still gets exactly the flow it has
 * today.
 */

function status(over: Partial<SetupStatus> = {}): SetupStatus {
  return {
    complete: false,
    config_path: "/data/config.toml",
    fields: [],
    templates: [],
    auth_modes: ["email"],
    build: {
      acp_in_build: false,
      acp_transport_mounted: false,
      mcp_in_build: false,
      harness_in_build: false,
      oauth_in_build: false,
    },
    companies: [],
    inference: { ready: false, provider: null, base_url: null },
    mail: { wired: false, echoes_code: false },
    ...over,
  };
}

/** What the control plane's projected credential looks like on the wire. */
const hosted = () =>
  status({
    inference: {
      ready: true,
      provider: "managed",
      base_url: "https://api.tinyhumans.ai/openai/v1",
    },
  });

/**
 * Routes by path, because the wizard makes three different calls through
 * `post` — the connection test, the roster design, and the apply — and the
 * apply body is what the payload assertions read.
 */
function clientWith(s: SetupStatus, seen: { body?: unknown } = {}): OpenCompanyClient {
  return {
    scopeFor: () => "/api/v1/company",
    get: async () => s,
    post: async (path: string, body: unknown) => {
      if (path.includes("/inference/test")) {
        return { ok: true, baseUrl: s.inference.base_url, model: "some-model" };
      }
      if (path.includes("/setup/roster")) {
        return { source: "model", agents: [{ role: "Operations", description: "Runs things" }] };
      }
      seen.body = body;
      return {
        complete: true,
        config_path: s.config_path,
        restart_required: [],
        seeded_company: null,
      };
    },
  } as unknown as OpenCompanyClient;
}

let container: HTMLDivElement;
let root: Root;

beforeEach(() => {
  (globalThis as unknown as { IS_REACT_ACT_ENVIRONMENT: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
  container = document.createElement("div");
  document.body.appendChild(container);
  root = createRoot(container);
});

afterEach(() => {
  act(() => root.unmount());
  container.remove();
});

async function show(client: OpenCompanyClient) {
  await act(async () => {
    root.render(createElement(SetupWizard, { client, onDone: () => {} }));
  });
}

const find = (testId: string) => container.querySelector(`[data-testid="${testId}"]`);

const all = (testId: string) => container.querySelectorAll(`[data-testid="${testId}"]`);

/** The slots the progress bar is actually drawing. */
const slots = () =>
  Array.from(container.querySelectorAll("[data-testid^='step-']")).map((el) =>
    el.getAttribute("data-testid"),
  );

/** The wizard's own progress line, e.g. `Review · step 4 of 4`. */
function stepLabel(): string {
  const match = container.textContent?.match(/(\w[\w -]*) · step \d+ of \d+/);
  return match ? match[0] : "";
}

function labelled(...wanted: string[]): HTMLButtonElement {
  const match = Array.from(container.querySelectorAll("button")).find((b) =>
    wanted.includes(b.textContent?.trim() ?? ""),
  );
  expect(match, `no button labeled ${wanted.join("/")}`).toBeTruthy();
  return match as HTMLButtonElement;
}

const next = async () =>
  act(async () => {
    labelled("Next", "Looks good").click();
  });

async function fill(testId: string, value: string) {
  const field = find(testId) as HTMLInputElement | HTMLTextAreaElement | null;
  expect(field, `no field ${testId}`).toBeTruthy();
  await act(async () => {
    const setter = Object.getOwnPropertyDescriptor(
      field instanceof HTMLTextAreaElement
        ? HTMLTextAreaElement.prototype
        : HTMLInputElement.prototype,
      "value",
    )!.set!;
    setter.call(field!, value);
    field!.dispatchEvent(new Event("input", { bubbles: true }));
  });
}

const settle = async () =>
  act(async () => {
    await new Promise((resolve) => setTimeout(resolve, 0));
  });

/**
 * Gets past step 0 onto step 1, and is a no-op where step 0 is absent.
 *
 * The flow opens on the setup-way choice, and the add-provider sequence sits
 * behind "Set it up yourself".
 */
async function chooseSelfManaged() {
  const option = find("setup-way-self-managed") as HTMLElement | null;
  if (!option) return;
  await act(async () => {
    option.click();
  });
  await next();
}

/**
 * Business -> sign-in -> account -> review, with no model step in front of it.
 *
 * Nothing here answers a model question, which is the assertion this helper
 * carries into every test that uses it: the walk completes without one.
 */
async function goToReview() {
  await fill("setup-field-industry", "E-commerce — homeware");
  await next(); // -> sign-in
  await next(); // -> account
  await fill("setup-field-email", "ada@example.com");
  await next(); // -> review
  await settle();
}

describe("a host that already reaches a model", () => {
  it("opens on the business question, with no model step and no slot for one", async () => {
    await show(clientWith(hosted()));

    expect(slots()).toEqual([
      "step-business",
      "step-signin",
      "step-account",
      "step-review",
    ]);
    // The count must drop with the step. A four-screen flow that says "of 5" is
    // telling the operator about a screen they will never be shown.
    expect(container.textContent).toContain("step 1 of 4");
    expect(find("setup-add-provider"), "step 1 must not render").toBeNull();
  });

  it("finishes without ever showing a key field or a connection test", async () => {
    await show(clientWith(hosted()));
    await goToReview();

    // Landed on Review, asserted before anything about what is absent —
    // otherwise the three checks below would also pass if the walk had stalled.
    expect(stepLabel(), "the walk should have reached Review").toMatch(/^Review · step/);
    expect(container.querySelector("#setup-key")).toBeNull();
    expect(find("setup-field-key")).toBeNull();
    expect(find("setup-test-connection")).toBeNull();
    expect((find("setup-finish") as HTMLButtonElement | null)?.disabled).toBe(false);
  });

  it("stores no inference provider for the company it builds", async () => {
    const seen: { body?: unknown } = {};
    await show(clientWith(hosted(), seen));
    await goToReview();

    await act(async () => {
      (find("setup-finish") as HTMLElement).click();
    });
    await settle();

    const body = seen.body as
      | { company?: { inference?: unknown }; fields?: Record<string, unknown> }
      | undefined;
    expect(body, "setup should have been applied").toBeTruthy();
    // The host resolves the managed endpoint from its own environment at
    // runtime. Writing a provider here would record a choice nobody made.
    expect(body?.company?.inference ?? null).toBeNull();
    expect(body?.fields ?? {}).not.toHaveProperty("tinyhumans_api_key");
  });

  it("says once, on review, that the model came with the host", async () => {
    await show(clientWith(hosted()));
    await goToReview();

    // Skipping silently is the failure mode: an operator who was never asked
    // for a model should find out where theirs came from in the flow.
    expect(all("setup-host-model")).toHaveLength(1);
    expect(find("setup-host-model")?.textContent).toMatch(/comes with this host/);
  });
});

describe("a host that reaches no model of its own", () => {
  it("still asks how this company connects, now behind the setup-way choice", async () => {
    await show(clientWith(status()));

    expect(find("setup-add-provider"), "step 1 is not step 0").toBeNull();

    await chooseSelfManaged();

    expect(slots()).toEqual([
      "step-setup-way",
      "step-self-managed-connect",
      "step-business",
      "step-signin",
      "step-account",
      "step-review",
    ]);
    expect(container.textContent).toContain("step 2 of 6");
    expect(find("setup-add-provider"), "step 1 should render").toBeTruthy();
  });

  it("still gates the managed branch on a verdict", async () => {
    await show(clientWith(status()));
    await act(async () => {
      (find("setup-way-managed") as HTMLElement).click();
    });
    await next();

    await next();
    expect(find("setup-problem"), "an untested connection must hold the step").toBeTruthy();
    expect(find("setup-field-key"), "and must not have left it").toBeTruthy();
  });

  it("says nothing about a host-provided model", async () => {
    await show(clientWith(status()));
    await chooseSelfManaged();

    // Connecting nothing answers the step, which is what lets this walk reach
    // Review without a credential.
    await next(); // -> business
    await goToReview();

    expect(stepLabel(), "the walk should have reached Review").toMatch(/^Review · step/);
    expect(all("setup-host-model")).toHaveLength(0);
  });
});

// @vitest-environment jsdom

import { act, createElement } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import type { OpenCompanyClient } from "@/api/client";
import type { TeamMemberDto } from "@/api/types";
import { ConnectionScopeProvider } from "@/connections/ConnectionContext";
import type { ConnectionId, LocalScope } from "@/connections/types";
import { SetupController } from "@/setup/SetupController";
import { markSetupRedesign, markSetupSkipped, setupRedesign, setupResuming } from "@/setup/state";

/**
 * The way back into setup after leaving it to wire a model.
 *
 * Not recording a skip for that navigation is only half the fix. This
 * controller stays mounted across hash changes, its gate re-evaluates only on
 * `(client, company, scope, deepLinked)`, and `evaluatedOnce` bars a second
 * unprompted open — so with nothing else done, an operator who followed "Set up
 * a model", configured one, and came back would find no dialog and an unstaffed
 * company, reachable only through the Team page's separate prompt. That is the
 * same dead end the skip caused, arrived at differently.
 *
 * So the departure records a debt and the return pays it, on both the routes a
 * return can take: an ordinary hash change, and a full reload (wiring a provider
 * can ask for a restart).
 */

/** One connection's view of a single-company host. */
const SCOPE: LocalScope = { connection: "test-connection" as ConnectionId, company: null };

/** The baseline every company carries — present, and not "staffed". */
const BASELINE: TeamMemberDto[] = ["operations", "page_builder", "researcher", "writer"].map(
  (id) => ({ id, role: "Analyst", inboxEnabled: false, global: true }) as TeamMemberDto,
);

const STAFFED: TeamMemberDto[] = [
  ...BASELINE,
  { id: "ada", role: "Operations", inboxEnabled: false } as TeamMemberDto,
];

function clientWith(roster: TeamMemberDto[]): OpenCompanyClient {
  return {
    scopeFor: (company: string | null) => `/api/v1/companies/${company}`,
    listTeam: async () => roster,
    // The dialog's own readiness check; `echo` keeps the notice on screen. The
    // role read is a second `get` on `/auth/me`; answer it as an admin so the
    // model CTAs this spec follows are offered.
    get: async (path: string) =>
      path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
    post: async () => ({ agents: [], template: "ecommerce", source: "fallback" }),
  } as unknown as OpenCompanyClient;
}

let container: HTMLDivElement;
let root: Root;

beforeEach(() => {
  (globalThis as unknown as { IS_REACT_ACT_ENVIRONMENT: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
  localStorage.clear();
  window.location.hash = "#/overview";
  container = document.createElement("div");
  document.body.appendChild(container);
  root = createRoot(container);
});

afterEach(() => {
  act(() => root.unmount());
  container.remove();
  localStorage.clear();
});

async function mount(client: OpenCompanyClient, deepLinked = false) {
  await act(async () => {
    root.render(
      createElement(ConnectionScopeProvider, {
        scope: SCOPE,
        children: createElement(SetupController, { client, company: null, deepLinked }),
      }),
    );
  });
}

const dialog = () => document.querySelector('[data-testid="setup-dialog"]');
const find = (testId: string) => document.querySelector(`[data-testid="${testId}"]`);

const modelLink = () =>
  Array.from(document.querySelectorAll("a")).find((a) => a.textContent?.trim() === "Set up a model");

const addModelLink = () =>
  Array.from(document.querySelectorAll("a")).find(
    (a) => a.textContent?.trim() === "Add a model in Settings",
  );

/** Navigate as the console does — a hash change the controller can hear. */
async function goTo(hash: string) {
  await act(async () => {
    window.location.hash = hash;
    window.dispatchEvent(new HashChangeEvent("hashchange"));
  });
}

/** Answer the three questions and let the build-out finish. */
async function runFlow() {
  const setField = async (testId: string, value: string) => {
    const field = document.querySelector(`[data-testid="${testId}"]`) as
      | HTMLInputElement
      | HTMLTextAreaElement
      | null;
    expect(field, `no field ${testId}`).toBeTruthy();
    await act(async () => {
      const setter = Object.getOwnPropertyDescriptor(
        field instanceof HTMLTextAreaElement
          ? HTMLTextAreaElement.prototype
          : HTMLInputElement.prototype,
        "value",
      )!.set!;
      setter.call(field, value);
      field!.dispatchEvent(new Event("input", { bubbles: true }));
    });
    await act(async () => {
      (document.querySelector('[data-testid="setup-next"]') as HTMLElement).click();
    });
  };
  await setField("setup-field-industry", "E-commerce — homeware");
  await setField("setup-field-teamHint", "");
  await setField("setup-field-automate", "");
  for (let i = 0; i < 40 && !addModelLink(); i++) {
    await act(async () => {
      await new Promise((r) => setTimeout(r, 60));
    });
  }
  expect(addModelLink(), "completion CTA never appeared").toBeTruthy();
}

/** Follow "Set up a model", which both closes the dialog and navigates. */
async function leaveForModelSettings() {
  const link = modelLink();
  expect(link, "no model link on the notice").toBeTruthy();
  await act(async () => {
    (link as HTMLElement).click();
  });
  // The anchor's onClick does not preventDefault, so jsdom queues its own
  // navigation to Settings as a deferred task. Drain it *before* driving the
  // hash change below — a macrotask queued before this flush must have run by
  // the time it lands, so it cannot later fire into a remount and revert the
  // address to Settings when a return (or reload) has moved it to the console.
  await act(async () => {
    await new Promise((r) => setTimeout(r, 0));
  });
  // jsdom does not follow the anchor's href, so drive the navigation it implies.
  // Deliberately the LEGACY address. Inference is `#/connections/inference`
  // now, and `console-route-rewrites.ts` resolves this one onto it without
  // rewriting the address bar — so a bookmark parks an operator on the model
  // page under a hash `onModelSettings` has to recognise or setup reopens on
  // top of them. Driving the gate from the old address is what covers that.
  // `#/settings/inference` since the model links were corrected off the dead
  // `#/settings/connections`, which named no settings page at all.
  await goTo("#/settings/inference");
}

describe("leaving to wire a model", () => {
  it("records a debt rather than a skip", async () => {
    await mount(clientWith(BASELINE));
    expect(dialog(), "setup should have opened by itself").toBeTruthy();

    await leaveForModelSettings();

    expect(dialog(), "should have closed for the navigation").toBeNull();
    expect(setupResuming(SCOPE)).toBe(true);
  });

  it("reopens setup when the operator navigates back", async () => {
    await mount(clientWith(BASELINE));
    await leaveForModelSettings();
    expect(dialog()).toBeNull();

    await goTo("#/overview");

    expect(dialog(), "the flow they went to enable is unreachable").toBeTruthy();
    expect(find("setup-question")).toBeTruthy();
  });

  it("stays shut while they are still on the settings page", async () => {
    await mount(clientWith(BASELINE));
    await leaveForModelSettings();
    // A sub-page of the same settings area is not "coming back".
    await goTo("#/settings/inference?provider=openrouter");
    expect(dialog()).toBeNull();
  });

  it("reopens after a reload on the way back, not one on the page itself", async () => {
    // Wiring a provider can ask for a restart, so the return is not always a
    // hash change. Two fresh mounts stand in for the two reloads.
    await mount(clientWith(BASELINE));
    await leaveForModelSettings();
    await act(async () => root.unmount());

    root = createRoot(container);
    // `deepLinked` as `AppShell` computes it for this address: a reload on
    // `#/settings/inference` is a named view, so nothing opens unprompted and
    // the resume is the only thing that could.
    await mount(clientWith(BASELINE), true);
    expect(dialog(), "reloaded on the settings page — they have not returned yet").toBeNull();

    window.location.hash = "#/overview";
    await act(async () => root.unmount());
    root = createRoot(container);
    await mount(clientWith(BASELINE), true);

    expect(dialog(), "a reload back on the console should resume setup").toBeTruthy();
  });

  it("does not reopen over a company someone else staffed meanwhile", async () => {
    await mount(clientWith(BASELINE));
    await leaveForModelSettings();
    await act(async () => root.unmount());

    root = createRoot(container);
    window.location.hash = "#/overview";
    await mount(clientWith(STAFFED), true);

    expect(dialog(), "a setup dialog over a team that already exists").toBeNull();
    expect(setupResuming(SCOPE), "debt should be dropped").toBe(
      false,
    );
  });

  it("re-reads the roster on a hash-change return instead of trusting the old answer", async () => {
    // A colleague staffs the company while the operator is wiring a model. The
    // hash-change return goes through the same `arrive` listener as any other,
    // which must re-read the roster — the empty answer captured before the
    // navigation is a snapshot, not a fact, and opening setup over a team that
    // now exists would stack a second one.
    const roster: TeamMemberDto[] = [...BASELINE];
    const client = clientWith(roster);
    await mount(client);
    await leaveForModelSettings();

    roster.push({ id: "ada", role: "Operations", inboxEnabled: false } as TeamMemberDto);

    await goTo("#/overview");

    expect(dialog(), "a setup dialog over a team that exists").toBeNull();
    expect(setupResuming(SCOPE), "debt should be dropped").toBe(false);
  });

  it("keeps the debt when the return's roster read fails, so a later return can retry", async () => {
    // A transient failure must not consume the resume. The dialog stays shut
    // because the roster is unknown, but the debt survives so the next arrival
    // or reload can retry — otherwise the flow the operator went to enable is
    // reachable again only through the Company-page prompt.
    let failing = false;
    const roster: TeamMemberDto[] = [...BASELINE];
    const client = {
      ...clientWith(roster),
      listTeam: async () => {
        if (failing) throw new Error("transient");
        return roster;
      },
    } as unknown as OpenCompanyClient;
    await mount(client);
    await leaveForModelSettings();

    failing = true;
    await goTo("#/overview");
    expect(dialog(), "unknown roster — must stay shut").toBeNull();
    expect(setupResuming(SCOPE), "debt must survive the failed read").toBe(true);

    // The next return reads successfully: the debt pays out and setup reopens.
    failing = false;
    await goTo("#/settings/inference");
    await goTo("#/overview");
    expect(dialog(), "the retried return should resume setup").toBeTruthy();
  });

  it("ignores a stale return read that resolves after the company switches", async () => {
    // A return from model settings starts a roster read. If the operator
    // switches companies before it resolves, the callback must not reopen setup
    // over the new company: the listener is removed on the switch, but the
    // in-flight read is not cancelled, so without a guard the callback's
    // `setOpen` would land on a controller rendering a company its read never
    // saw — and the dialog it opened would then run replacement against the
    // wrong company's roster.
    let acmeReads = 0;
    let resolveAcme!: (roster: TeamMemberDto[]) => void;
    const acmeRead = new Promise<TeamMemberDto[]>((resolve) => {
      resolveAcme = resolve;
    });
    const client = {
      ...clientWith([...BASELINE]),
      listTeam: async (company: string | null) => {
        // The second acme read — the one `arrive` starts on the return — is the
        // read we hold open. Every other read is served.
        if (company !== "acme") return [...STAFFED];
        acmeReads++;
        if (acmeReads >= 2) return acmeRead;
        return [...BASELINE];
      },
    } as unknown as OpenCompanyClient;
    const render = (company: string | null) =>
      act(async () => {
        root.render(
          createElement(ConnectionScopeProvider, {
            scope: SCOPE,
            children: createElement(SetupController, { client, company, deepLinked: false }),
          }),
        );
      });

    // Mount on acme; the gate read is served and setup offers itself.
    await render("acme");
    expect(dialog(), "setup should have opened").toBeTruthy();
    await leaveForModelSettings();

    // Return to acme: `arrive` starts the roster read we hold open.
    await goTo("#/overview");
    expect(dialog(), "return read in flight").toBeNull();

    // Switch to a second company before the read lands. The stale callback
    // must not open setup over it — the second company's own gate read is the
    // only thing allowed to decide that.
    await render("globex");
    await act(async () => {
      resolveAcme([...BASELINE]);
    });

    expect(dialog(), "stale return read reopened setup over the new company").toBeNull();
  });

  it('drops the debt when the operator then says "I\'ll do this later"', async () => {
    await mount(clientWith(BASELINE));
    await leaveForModelSettings();
    await goTo("#/overview");
    expect(dialog()).toBeTruthy();

    await act(async () => {
      (find("setup-skip") as HTMLElement).click();
    });

    expect(dialog()).toBeNull();
    expect(setupResuming(SCOPE)).toBe(false);

    // And it stays shut across a return trip: "later" means later.
    await goTo("#/settings/inference");
    await goTo("#/overview");
    expect(dialog()).toBeNull();
  });
});

describe("the skip still suppresses the unprompted offer", () => {
  it("does not open on a company the operator already skipped", async () => {
    markSetupSkipped(SCOPE);
    await mount(clientWith(BASELINE));
    expect(dialog()).toBeNull();
  });
});

describe("leaving the completion screen to wire a model", () => {
  it("records a redesign debt, and the return reopens in redesign mode", async () => {
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...BASELINE],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async () => ({}),
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });

    // The completion CTA is a *navigation*, not a finish: the shipped team is
    // to be redesigned on the return, and the run must not be treated as done.
    expect(dialog(), "should close for the navigation").toBeNull();
    expect(setupRedesign(SCOPE), "no redesign debt recorded").toBe(true);

    await goTo("#/overview");

    expect(dialog(), "the redesign they were owed never reopened").toBeTruthy();
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();
  });

  it("replaces only the fallback team when another operator staffs someone meanwhile", async () => {
    // The redesign's replacement is bounded by the team the first pass actually
    // created, captured when the operator left for model settings — not by the
    // roster as it reads on return. A colleague who staffs a teammate while
    // those settings were open is doing their own work; deleting that row would
    // remove someone who was never told they were provisional.
    const removed: string[] = [];
    const roster: TeamMemberDto[] = [...BASELINE];
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...roster],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [
          { name: "Ada", role: "Operations", description: "Runs the desk." },
          { name: "Cara", role: "Support", description: "Answers the inbox." },
        ],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async (input: { name: string; role: string }) => {
        // The host mints ids from the name, unique against the roster it already
        // holds (issue #686) — a replacing build-out's creates run while the
        // rows they replace still exist, so a second Ada becomes "ada-2". The
        // replacement sweep below must not then remove the new rows.
        const base = input.name.toLowerCase();
        let id = base;
        for (let suffix = 2; roster.some((m) => m.id === id); suffix++) {
          id = `${base}-${suffix}`;
        }
        const member = { id, role: input.role, inboxEnabled: false } as TeamMemberDto;
        roster.push(member);
        return member;
      },
      removeTeamMember: async (id: string) => {
        removed.push(id);
      },
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    // Leave for model settings, persisting the fallback team as the redesign's
    // boundary — the first pass created exactly two teammates.
    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });
    expect(setupRedesign(SCOPE)).toBe(true);

    // A colleague staffs a teammate while the settings page is open.
    roster.push({ id: "bob", role: "Support", inboxEnabled: false } as TeamMemberDto);

    // Return: the redesign reopens, and the second build-out must replace only
    // the fallback team — ada and cara — leaving bob, someone else's work, alone.
    await goTo("#/overview");
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();
    await runFlow();

    expect(removed, "the fallback team should be replaced").toEqual(["ada", "cara"]);
    expect(removed, "an agent staffed while settings were open must survive").not.toContain("bob");
  });

  it("does not reopen a redesign whose fallback team another operator already replaced", async () => {
    // The redesign debt names the team the first pass created. If a colleague
    // replaces that team while model settings are open, the debt is stale —
    // reopening redesign would build a full roster and sweep nothing (the
    // recorded rows are gone), stacking a second team over their work.
    const roster: TeamMemberDto[] = [...BASELINE];
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...roster],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async () => ({ id: "ada" }),
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });
    expect(setupRedesign(SCOPE)).toBe(true);

    // The colleague replaces the fallback team with their own while the
    // settings page is open: the row the debt names is gone.
    roster.push({ id: "zoe", role: "Operations", inboxEnabled: false } as TeamMemberDto);

    await goTo("#/overview");

    expect(dialog(), "setup over a team the redesign no longer names").toBeNull();
    expect(setupRedesign(SCOPE), "the stale debt should be dropped").toBe(false);
  });

  it("reopens as a first run, not a redesign, when the fallback team was deleted", async () => {
    // The debt's team is gone and nobody has staffed the company since — the
    // return should offer first-run setup, not a redesign over nothing. A
    // redesign here would claim a replacement while sweeping zero rows.
    const roster: TeamMemberDto[] = [...BASELINE];
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...roster],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async () => ({ id: "ada" }),
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });
    expect(setupRedesign(SCOPE)).toBe(true);

    // The fallback team is gone entirely — the company is empty again.
    await goTo("#/overview");

    expect(dialog(), "the return should offer setup").toBeTruthy();
    expect(find("setup-redesign-notice"), "reopened as a redesign over nothing").toBeNull();
    expect(setupRedesign(SCOPE), "the stale debt should be dropped").toBe(false);
  });

  it("keeps the redesign debt across a reload after the return reopens it", async () => {
    // The redesign reopens the moment the operator returns, but the replacement
    // build-out has not run yet — the fallback team is still what the gate
    // calls staffed. A reload or crash in that window must not lose the debt:
    // without it the ordinary gate offers nothing and the owed redesign is
    // unreachable.
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...BASELINE],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async () => ({}),
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });
    // The anchor's default is a navigation to Settings; jsdom follows it as a
    // deferred task, so absorb that before driving the return — otherwise it
    // can land mid-reload and leave the address on Settings when the fresh
    // mount re-evaluates the gate.
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
    expect(setupRedesign(SCOPE)).toBe(true);

    await goTo("#/overview");
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();
    // The debt outlived the reopen.
    expect(setupRedesign(SCOPE), "the return paid the redesign debt").toBe(true);

    // A fresh mount stands in for the reload mid-redesign. The kept debt is the
    // only thing that can reopen replacing mode: `deepLinked` suppresses the
    // ordinary gate, and the fallback roster reads as staffed.
    await act(async () => root.unmount());
    root = createRoot(container);
    await mount(client, true);

    expect(dialog(), "the owed redesign did not come back after a reload").toBeTruthy();
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();
    expect(setupRedesign(SCOPE)).toBe(true);
  });

  it("drops the redesign debt when the operator says 'I'll do this later' mid-redesign", async () => {
    // Skip is an explicit decline, not a hold: the debt must not re-offer a
    // redesign the operator just turned down.
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...BASELINE],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "fallback",
        reason: "no_model",
      }),
      addTeamMember: async () => ({}),
    } as unknown as OpenCompanyClient;
    await mount(client);
    await runFlow();

    await act(async () => {
      (addModelLink() as HTMLElement).click();
    });
    // Absorb the anchor's deferred Settings navigation so it cannot fire into
    // the skip click below.
    await act(async () => {
      await new Promise((r) => setTimeout(r, 0));
    });
    expect(setupRedesign(SCOPE)).toBe(true);

    await goTo("#/overview");
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();

    await act(async () => {
      (find("setup-skip") as HTMLElement).click();
    });

    expect(dialog()).toBeNull();
    expect(setupRedesign(SCOPE), "skip should cancel the owed redesign").toBe(false);
  });

  it("clears the redesign debt when the replacement is designed, so a reload cannot reopen it", async () => {
    // A designed replacement pays the redesign debt: the fallback team the debt
    // named has been swept and replaced, so a reload on the completion screen
    // must not reopen redesign over the new team. The whole record is cleared —
    // skipped and resuming included — exactly as completing setup would.
    const roster: TeamMemberDto[] = [...BASELINE];
    const removed: string[] = [];
    const client = {
      scopeFor: () => "/api/v1/companies/acme",
      listTeam: async () => [...roster],
      get: async (path: string) =>
        path.endsWith("/auth/me") ? { role: "admin" } : { cognition: "echo" },
      post: async () => ({
        agents: [{ name: "Ada", role: "Operations", description: "Runs the desk." }],
        template: "ecommerce",
        source: "model",
      }),
      addTeamMember: async () => {
        const member = { id: "ada", role: "Operations", inboxEnabled: false } as TeamMemberDto;
        roster.push(member);
        return member;
      },
      removeTeamMember: async (id: string) => {
        removed.push(id);
      },
    } as unknown as OpenCompanyClient;

    // Seed the debt the operator is owed: a fallback pass shipped f1 and they
    // left to wire a model, naming that row as the replacement's boundary.
    roster.push({ id: "f1", role: "Operations", inboxEnabled: false } as TeamMemberDto);
    markSetupRedesign(SCOPE, ["f1"]);

    await mount(client);

    // The debt reopens the dialog in replacing mode, without any force flag.
    expect(dialog(), "the owed redesign did not reopen").toBeTruthy();
    expect(find("setup-redesign-notice"), "not reopened in replacing mode").toBeTruthy();

    const setField = async (testId: string, value: string) => {
      const field = document.querySelector(`[data-testid="${testId}"]`) as
        | HTMLInputElement
        | HTMLTextAreaElement
        | null;
      expect(field, `no field ${testId}`).toBeTruthy();
      await act(async () => {
        const setter = Object.getOwnPropertyDescriptor(
          field instanceof HTMLTextAreaElement
            ? HTMLTextAreaElement.prototype
            : HTMLInputElement.prototype,
          "value",
        )!.set!;
        setter.call(field, value);
        field!.dispatchEvent(new Event("input", { bubbles: true }));
      });
      await act(async () => {
        (document.querySelector('[data-testid="setup-next"]') as HTMLElement).click();
      });
    };
    await setField("setup-field-industry", "E-commerce — homeware");
    await setField("setup-field-teamHint", "");
    await setField("setup-field-automate", "");
    for (let i = 0; i < 40 && !find("setup-finish"); i++) {
      await act(async () => {
        await new Promise((r) => setTimeout(r, 60));
      });
    }

    expect(find("setup-finish"), "designed build-out never finished").toBeTruthy();
    expect(removed, "the fallback row the debt named should be swept").toEqual(["f1"]);
    // The whole record is gone — redesign, resuming and skip all cleared.
    expect(setupRedesign(SCOPE), "the designed replacement should pay the debt").toBe(false);
    expect(setupResuming(SCOPE)).toBe(false);
  });
});

// @vitest-environment jsdom

import { act, createElement } from "react";
import { createRoot, type Root } from "react-dom/client";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import type { SearchHit } from "@/api/workspace";
import { SECRETS_LABEL } from "@/lib/workspace";
import { SearchResults } from "@/views/workspace/SearchResults";

/**
 * Issue #1465, the search half.
 *
 * Operator search is deliberately unfiltered — `search_workspace` keeps the
 * whole tree while `search_workspace_for_agent` drops `secrets/` — which is
 * right, and is exactly why a private note used to come back in this list
 * looking like any other. A search replaces the tree in the explorer pane, so a
 * hit row is the only thing on screen: the row that says nothing is the row a
 * screen-shared console leaks.
 */

let container: HTMLDivElement;
let root: Root;

beforeEach(() => {
  (globalThis as unknown as { IS_REACT_ACT_ENVIRONMENT: boolean }).IS_REACT_ACT_ENVIRONMENT = true;
  container = document.createElement("div");
  document.body.appendChild(container);
  root = createRoot(container);
});

afterEach(() => {
  act(() => root.unmount());
  container.remove();
});

function hit(partial: Partial<SearchHit> & { id: string; name: string; path: string }): SearchHit {
  return {
    kind: "file",
    parentId: null,
    updatedAt: 0,
    createdBy: { kind: "seed" },
    updatedBy: { kind: "seed" },
    matched: "content",
    ...partial,
  } as SearchHit;
}

const HITS: SearchHit[] = [
  hit({ id: "keys", name: "Stripe keys.md", path: "secrets/Stripe keys.md" }),
  hit({ id: "deep", name: "Twilio.md", path: "secrets/vendors/Twilio.md" }),
  // An ordinary note, and a lookalike folder that is ordinary shared content
  // host-side — marking it would promise a privacy it does not have.
  hit({ id: "runbook", name: "Runbook.md", path: "Playbooks/Runbook.md" }),
  hit({ id: "old", name: "Archived key.md", path: "secrets-old/Archived key.md" }),
];

function renderHits(hits: SearchHit[]) {
  act(() =>
    root.render(
      createElement(SearchResults, {
        query: "key",
        hits,
        total: hits.length,
        loading: false,
        error: null,
        onOpen: () => {},
        rosterNames: new Map(),
      }),
    ),
  );
}

function rowFor(id: string): HTMLElement {
  const row = container.querySelector<HTMLElement>(`[data-node-id="${id}"]`);
  if (!row) throw new Error(`no hit row for ${id}`);
  return row;
}

function markerIn(id: string) {
  return rowFor(id).querySelector('[data-testid="workspace-search-secret"]');
}

describe("a note the agents cannot read, in the search hit list", () => {
  it("says so on the row", () => {
    renderHits(HITS);
    expect(markerIn("keys")?.textContent).toContain(SECRETS_LABEL);
    // The rule travels with the marker for a pointer, so the label is not a
    // bare two words — the tree row and the note header carry the same one.
    expect(markerIn("keys")?.getAttribute("title")).toContain("cannot list, read, search or write");
  });

  it("marks a note nested deeper than the folder itself", () => {
    renderHits(HITS);
    expect(markerIn("deep")).not.toBeNull();
  });

  it("leaves ordinary hits unmarked", () => {
    renderHits(HITS);
    expect(markerIn("runbook")).toBeNull();
    expect(markerIn("old")).toBeNull();
  });

  it("keeps the origin badge, unlike the derived marking", () => {
    // A `Seeded` note under `secrets/` really was seeded — the host lays down
    // one README there on first boot — so both badges are true and say
    // different things. (`derived/` suppresses `Seeded` because it is false
    // there; see #1377.)
    renderHits(HITS);
    expect(rowFor("keys").textContent).toContain("Seeded");
  });
});

import { describe, expect, it } from "vitest";

import { credentialAffordance } from "@/views/connections/McpServersSection";

/**
 * Issue #1260. The MCP row offered a **Sign in** button on a server whose OAuth
 * could never complete: Slack's MCP endpoint answers `401` with a proper
 * resource-metadata challenge but advertises no RFC 7591 dynamic client
 * registration, so there is no client to mint. `POST …/oauth/start` refused
 * with a `400` naming the real remedy — paste a static token — which the
 * operator could only read by pressing a button that could not work.
 *
 * The host now distinguishes the two states. These pin the console half: which
 * control a row offers is a function of that hint and nothing else.
 */
describe("credentialAffordance", () => {
  it("offers sign-in only when the host says sign-in can complete", () => {
    expect(credentialAffordance("oauth_required")).toBe("sign_in");
  });

  it("offers a token field when OAuth is required but undrivable", () => {
    expect(credentialAffordance("static_token_required")).toBe("add_token");
  });

  it("never offers sign-in for a server that cannot complete one", () => {
    // The regression itself. Both codes carry `status: needs_config` and both
    // read as "an auth problem"; only this distinction stops the unusable
    // button coming back.
    expect(credentialAffordance("static_token_required")).not.toBe("sign_in");
  });

  it("routes a plain credential prompt to the same field", () => {
    expect(credentialAffordance("credential_required")).toBe("add_token");
  });

  it("offers the token field to a credential the server saw and refused", () => {
    // `token_rejected` fell to the default arm and got no control, under a
    // message telling the operator to "update it and Test again" — the one
    // hint that names a stored credential still got no way to replace it.
    expect(credentialAffordance("token_rejected")).toBe("add_token");
    for (const source of ["manifest", "runtime", "default"] as const) {
      expect(credentialAffordance("token_rejected", { source, status: "needs_config" })).toBe(
        "add_token",
      );
    }
  });

  it("offers nothing for a healthy server or an unknown code", () => {
    // A server that probed `ok` carries no hint at all, and must not sprout a
    // credential control; an unrecognised future code must not either, because
    // guessing which control it wants is how the wrong one gets offered.
    expect(credentialAffordance(undefined)).toBe("none");
    expect(credentialAffordance("some_code_added_later")).toBe("none");
  });

  it("leaves every List A provenance on the hint alone", () => {
    // Issue #1270 added a second parameter. The rule for a row that has a List
    // A declaration is unchanged — it is still a function of the hint and
    // nothing else, whether or not the caller passes the row.
    for (const source of ["manifest", "runtime", "default"] as const) {
      expect(credentialAffordance("oauth_required", { source, status: "needs_config" })).toBe(
        "sign_in",
      );
      expect(credentialAffordance("static_token_required", { source, status: "needs_config" })).toBe(
        "add_token",
      );
      expect(credentialAffordance(undefined, { source, status: "ok" })).toBe("none");
    }
  });
});

/**
 * Issue #1270. A directory install keeps its credentials as *named env values*
 * in the host's registry store, and its row's `name` is a display slug that
 * addresses no List A declaration. So both of List A's controls are wrong for
 * it twice over: `POST …/oauth/start` and `PUT …/mcp/servers/{name}` answer
 * `no MCP server named …`, and the value they collect would be written to a
 * store this server is not dialled from.
 */
describe("credentialAffordance — directory installs", () => {
  it("routes a registry row to its own env rotation", () => {
    expect(credentialAffordance(undefined, { source: "registry", status: "needs_config" })).toBe(
      "rotate_env",
    );
  });

  it("offers no credential control at all when the install wants a browser sign-in", () => {
    // The env form collects named values for the registry store; it cannot
    // store a browser session, and no registry route starts one. Routing this
    // row to `rotate_env` put a Save button under a host message that already
    // said a pasted token would not work.
    expect(credentialAffordance("oauth_required", { source: "registry", status: "needs_config" })).toBe(
      "none",
    );
  });

  it("does not need a hint to know a registry row wants a credential", () => {
    // The reason `status` is consulted at all. The host's registry projection
    // emits a stable `authHint` only when the upstream connection reported one,
    // so an install refused for want of a credential can arrive as
    // `needs_config` with no hint — and a rule keyed on the hint alone would
    // offer that row nothing at all.
    expect(credentialAffordance(undefined, { source: "registry", status: "needs_config" })).not.toBe(
      "none",
    );
  });

  it("never offers a registry row a control that writes to the wrong store", () => {
    for (const hint of [
      undefined,
      "oauth_required",
      "static_token_required",
      "credential_required",
      "token_rejected",
    ]) {
      const offered = credentialAffordance(hint, {
        source: "registry",
        status: "needs_config",
      });
      expect(offered).not.toBe("sign_in");
      expect(offered).not.toBe("add_token");
    }
  });

  it("offers nothing to a registry row that is not asking for one", () => {
    for (const status of ["ok", "error", "unknown"] as const) {
      expect(credentialAffordance(undefined, { source: "registry", status })).toBe("none");
    }
    expect(credentialAffordance(undefined, { source: "registry" })).toBe("none");
  });
});

use super::*;

#[test]
fn pkce_challenge_is_s256_of_verifier() {
    let (verifier, challenge) = gen_pkce();
    assert!(
        (43..=128).contains(&verifier.len()),
        "verifier in PKCE range: {}",
        verifier.len()
    );
    let expected = B64.encode(Sha256::digest(verifier.as_bytes()));
    assert_eq!(challenge, expected);
}

#[test]
fn callback_uri_appends_route_and_trims_trailing_slash() {
    assert_eq!(
        callback_redirect_uri("http://127.0.0.1:8080"),
        "http://127.0.0.1:8080/oauth/mcp/callback"
    );
    assert_eq!(
        callback_redirect_uri("https://acme.example/"),
        "https://acme.example/oauth/mcp/callback"
    );
}

#[test]
fn authorize_url_carries_pkce_and_resource() {
    let url = build_authorize_url(
        "https://as.example/authorize",
        "client-123",
        "http://127.0.0.1:8080/oauth/mcp/callback",
        "challenge-abc",
        "state-xyz",
        "https://mcp.example/mcp",
    )
    .expect("url");
    assert!(url.contains("response_type=code"));
    assert!(url.contains("client_id=client-123"));
    assert!(url.contains("code_challenge=challenge-abc"));
    assert!(url.contains("code_challenge_method=S256"));
    assert!(url.contains("state=state-xyz"));
    // The MCP server URL is the `resource`, percent-encoded.
    assert!(url.contains("resource=https%3A%2F%2Fmcp.example%2Fmcp"));
}

#[test]
fn parse_token_response_extracts_fields() {
    let v = json!({"access_token":"a","refresh_token":"r","expires_in":3600});
    let t = parse_token_response(&v).unwrap();
    assert_eq!(t.access_token, "a");
    assert_eq!(t.refresh_token.as_deref(), Some("r"));
    assert_eq!(t.expires_in, Some(3600));
    // refresh_token / expires_in are optional; access_token is required.
    let minimal = parse_token_response(&json!({"access_token":"x"})).unwrap();
    assert_eq!(minimal.access_token, "x");
    assert!(minimal.refresh_token.is_none());
    assert!(parse_token_response(&json!({"token_type":"bearer"})).is_err());
}

#[test]
fn oauth_material_secret_values_cover_every_token() {
    // The security invariant: access token, refresh token, and client secret
    // all reach the scrubber's known-secret set.
    let material = AuthMaterial::OAuth {
        access_token: "at-secret".into(),
        refresh_token: Some("rt-secret".into()),
        client_id: "cid".into(),
        client_secret: Some("cs-secret".into()),
        token_endpoint: "https://as/token".into(),
        expires_at: 0,
    };
    let secrets = material.secret_values();
    assert!(secrets.contains(&"at-secret".to_string()));
    assert!(secrets.contains(&"rt-secret".to_string()));
    assert!(secrets.contains(&"cs-secret".to_string()));
    // The client id is NOT a secret and must not be in the set.
    assert!(!secrets.contains(&"cid".to_string()));
    assert!(material.is_configured());
}

#[test]
fn needs_refresh_only_fires_near_expiry() {
    let fresh = AuthMaterial::OAuth {
        access_token: "a".into(),
        refresh_token: None,
        client_id: "c".into(),
        client_secret: None,
        token_endpoint: "https://as/token".into(),
        expires_at: now_unix() + 3600,
    };
    assert!(!needs_refresh(&fresh, 60));
    let stale = AuthMaterial::OAuth {
        access_token: "a".into(),
        refresh_token: None,
        client_id: "c".into(),
        client_secret: None,
        token_endpoint: "https://as/token".into(),
        expires_at: now_unix() + 30,
    };
    assert!(needs_refresh(&stale, 60));
    // A non-OAuth material never needs refresh.
    assert!(!needs_refresh(&AuthMaterial::Bearer("t".into()), 60));
}

#[tokio::test]
async fn guard_blocks_non_https_and_local_targets() {
    use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

    // Every case here short-circuits before DNS (bad scheme, bad URL, or an
    // IP-literal host), so the test never touches the network.
    // Scheme: plain http is refused outright (SSRF loves cleartext localhost).
    assert!(
        guard_endpoint("http://as.example/token", "token")
            .await
            .is_err()
    );
    // IP-literal hosts in blocked ranges are rejected without DNS.
    assert!(
        guard_endpoint("https://127.0.0.1/token", "token")
            .await
            .is_err()
    );
    assert!(
        guard_endpoint("https://10.0.0.5/register", "registration")
            .await
            .is_err()
    );
    assert!(
        guard_endpoint("https://192.168.1.1/token", "token")
            .await
            .is_err()
    );
    // The cloud metadata endpoint — the canonical SSRF target — is link-local.
    assert!(
        guard_endpoint("https://169.254.169.254/latest/meta-data", "token")
            .await
            .is_err()
    );
    assert!(
        guard_endpoint("https://[::1]/token", "token")
            .await
            .is_err()
    );
    // A syntactically bad URL is a clean rejection, not a panic.
    assert!(guard_endpoint("not a url", "token").await.is_err());

    // The IP-classification helper covers v4 + v6 ranges directly.
    assert!(is_blocked_ip(&IpAddr::V4(Ipv4Addr::new(
        169, 254, 169, 254
    ))));
    assert!(is_blocked_ip(&IpAddr::V4(Ipv4Addr::new(172, 16, 0, 1))));
    assert!(is_blocked_ip(&IpAddr::V6(Ipv6Addr::LOCALHOST)));
    assert!(is_blocked_ip(&IpAddr::V6("fc00::1".parse().unwrap())));
    assert!(is_blocked_ip(&IpAddr::V6("fe80::1".parse().unwrap())));
    // A routable public address passes the classifier.
    assert!(!is_blocked_ip(&IpAddr::V4(Ipv4Addr::new(93, 184, 216, 34))));
    assert!(!is_blocked_ip(&IpAddr::V6(
        "2606:2800:220:1::1".parse().unwrap()
    )));
}

